(()=>{'use strict';const $=s=>document.querySelector(s),make=(t,s)=>{const e=document.createElement(t);e.textContent=s;return e;};let user,target;
async function api(path,body){const r=await fetch('/api/admin/accounts'+path,{cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Не удалось выполнить действие.');return d;}
async function save(form,self){const data=new FormData(form);if(data.get('password')!==data.get('confirm'))throw Error('Пароли не совпадают.');const d=await api('/password',{userId:self?user.id:target,password:data.get('password'),...(self?{currentPassword:data.get('currentPassword')}:{})});form.reset();if(d.signInAgain){location.href='/admin/';return;}$('#password-dialog').close();$('#account-message').textContent='Пароль изменён. Прежние сеансы сотрудника завершены.';}
for(const [selector,self] of [['#own-password',true],['#reset-password',false]])$(selector).onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');if(button.disabled)return;button.disabled=true;const out=self?$('#account-message'):$('#password-error');out.textContent='';try{await save(e.currentTarget,self);}catch(err){out.textContent=err.message;}finally{button.disabled=false;}};
$('#password-close').onclick=()=>$('#password-dialog').close();
async function list(){const d=await api('');const root=$('#account-list');root.replaceChildren();for(const u of d.items){const row=make('article','');row.className='account-row';row.append(make('strong',u.login),make('span',u.archived_at?'Удалён (история сохранена)':({admin:'Администратор',staff:'Прокат и кафе',waiter:'Официант'}[u.role])));if(!u.archived_at&&u.id!==user.id){const reset=make('button','Сменить пароль');reset.onclick=()=>{target=u.id;$('#password-heading').textContent='Пароль: '+u.login;$('#reset-password').reset();$('#password-error').textContent='';$('#password-dialog').showModal();};const del=make('button','Удалить доступ');del.className='account-delete';del.onclick=async()=>{if(!confirm('Удалить доступ '+u.login+'? Вход будет закрыт. История смен, зарплат и действий сохранится.'))return;del.disabled=true;try{await api('/archive',{userId:u.id});await list();$('#account-message').textContent='Доступ закрыт. История сохранена.';}catch(e){$('#account-message').textContent=e.message;del.disabled=false;}};row.append(reset,del);}root.append(row);}}
(async()=>{try{const r=await fetch('/api/admin/session',{cache:'no-store'});({user}=await r.json());if(!user){$('#account-login').hidden=false;return;}$('#own-account').hidden=false;if(user.role==='admin'){$('#account-admin').hidden=false;await list();}}catch(e){$('#account-message').textContent=e.message;}})();})();
